<?php
declare(strict_types=1); require_once __DIR__.'/../includes/layout.php'; require_admin();
$rows=db()->query("SELECT r.*,b.title,COALESCE(u.fullname,r.walkin_name) customer,IF(r.user_id IS NULL,'Walk-in Customer','Member') customer_type,DATEDIFF(CURDATE(),r.due_date) overdue FROM rentals r JOIN books b ON b.id=r.book_id LEFT JOIN users u ON u.id=r.user_id WHERE r.status='borrowed' ORDER BY r.due_date")->fetchAll();
page_start('รับคืนหนังสือ','returns'); ?>
<div class="page-head"><div><h1>รับคืนหนังสือ</h1><p>บันทึกเวลาคืนจริงและคำนวณค่าปรับ 10 บาทต่อวันที่เกินกำหนด</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>ลูกค้า</th><th>ประเภท</th><th>หนังสือ</th><th>เริ่มเช่า</th><th>กำหนดคืน</th><th>ค่าเช่า</th><th>ค่าปรับปัจจุบัน</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$fine=max(0,(int)$r['overdue'])*10;?><tr class="<?=$fine?'overdue':''?>"><td><?=e($r['customer'])?></td><td><?=e($r['customer_type'])?></td><td><?=e($r['title'])?></td><td><?=thai_date($r['borrowed_at'],true)?></td><td><?=thai_date($r['due_date'])?></td><td><?=format_money($r['rental_total'])?> บาท</td><td class="money"><?=format_money($fine)?> บาท</td><td><form method="post" action="<?=base_url('actions/return-book.php')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-primary" data-confirm="ยืนยันว่ารับคืนหนังสือแล้ว?">รับคืน</button></form></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="8" class="empty">ไม่มีรายการเช่าที่ยังไม่คืน</td></tr><?php endif?></tbody></table></div></section>
<?php page_end(); ?>

